"""Task-owned real Mac2 application experiment. Not product code or a driver wrapper."""
import argparse
import hashlib
import json
import os
import re
import shutil
import signal
import subprocess
import sys
import tempfile
import threading
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path('$SOURCE_ROOT')
sys.path.insert(0, str(ROOT))
from tests.e2e.native_client import run_native, serialize
from server_utils import free_port, http_json, read_session_ids, parse_transactions, wait_group_gone, wait_port_closed, normalize_script, session_id_of, digest

TEXTEDIT = 'com.apple.TextEdit'
FINDER = 'com.apple.finder'
ELEMENT_KEY = 'element-6066-11e4-a52e-4f735466cecf'
TITLE_ATTRIBUTES = {'title', 'name', 'label', 'amText'}
ATTRIBUTE_ALLOWLIST = {
    'title', 'name', 'label', 'value', 'text', 'selected', 'displayed', 'enabled',
    'identifier', 'amText', 'amType', 'amHasKeyboardInputFocus', 'amIdentifier',
}
NETWORK_ERROR_TYPES = {
    'ConnectionError', 'ConnectionRefusedError', 'ConnectionResetError',
    'MaxRetryError', 'NewConnectionError', 'RemoteDisconnected', 'URLError',
    'HTTPError', 'TimeoutError', 'WebDriverException',
}
SAFE_SCRIPTS = {
    'macos: keys', 'macos: click', 'macos: doubleclick', 'macos: deeplink',
    'macos: activateapp', 'macos: terminateapp', 'macos: queryappstate',
}


def now():
    return datetime.now(timezone.utc).isoformat()


def desktop():
    code = '''ObjC.import("AppKit");const w=$.NSWorkspace.sharedWorkspace;const a=w.runningApplications;let t=[];for(let i=0;i<a.count;i++){let p=a.objectAtIndex(i);if(p.bundleIdentifier&&!p.bundleIdentifier.isNil()&&ObjC.unwrap(p.bundleIdentifier)==="com.apple.TextEdit")t.push({pid:Number(p.processIdentifier),hidden:Boolean(p.hidden)});}const f=w.frontmostApplication;JSON.stringify({textedit:t,frontmostBundleId:f&&!f.isNil()&&f.bundleIdentifier&&!f.bundleIdentifier.isNil()?ObjC.unwrap(f.bundleIdentifier):null});'''
    result = subprocess.run(['osascript','-l','JavaScript','-e',code],check=True,capture_output=True,text=True,timeout=15)
    return json.loads(result.stdout)


def logical_text(path):
    result = subprocess.run(['textutil','-convert','txt','-stdout',str(path)],check=True,capture_output=True,text=True,timeout=10)
    return result.stdout.strip()


def file_state(root):
    return {str(p.relative_to(root)):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size} for p in root.rglob('*') if p.is_file()}


def returned(txn):
    values = txn.get('responding',[])
    return values[-1].get('value') if values else None


def _utc(value):
    if not isinstance(value,str):
        return None
    text = value.strip()
    if not text:
        return None
    if text.endswith(('Z','z')):
        text = text[:-1] + '+00:00'
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        return None
    return parsed.astimezone(timezone.utc)


def _window(value):
    if not isinstance(value,dict):
        return None
    started = _utc(value.get('startedAt'))
    completed = _utc(value.get('completedAt'))
    if started is None or completed is None or started > completed:
        return None
    return started, completed


def _inside(inner, outer):
    return outer[0] <= inner[0] and inner[1] <= outer[1]


def _after(value, stamp):
    moment = _utc(value)
    boundary = _utc(stamp)
    return moment is not None and boundary is not None and moment >= boundary


def _status_ok(rec):
    return rec.get('status') == 200


def _scalar_text(value):
    return value if isinstance(value,str) else None


def _scalar_bool(value):
    if isinstance(value,bool):
        return value
    if isinstance(value,str) and value.strip().lower() in {'true','yes','1'}:
        return True
    if isinstance(value,str) and value.strip().lower() in {'false','no','0'}:
        return False
    return None


def _response_element_ids(value):
    result = []
    if isinstance(value,dict) and isinstance(value.get(ELEMENT_KEY),str):
        result.append(value[ELEMENT_KEY])
    elif isinstance(value,list):
        for item in value:
            if isinstance(item,dict) and isinstance(item.get(ELEMENT_KEY),str):
                result.append(item[ELEMENT_KEY])
    return result[:64]


def _path_kind(path):
    pieces = path.split('/')[3:] if path.startswith('/session/') else [path]
    return [piece if not (len(piece) > 20 and piece not in {'execute','attribute','elements','selected','displayed','click','value','window','handles','element','source'}) else '$ID' for piece in pieces]


def _matches(value, expected):
    text = value if isinstance(value,str) else json.dumps(value,ensure_ascii=False)
    return sorted(name for name,needle in expected.items() if needle and needle in text)


def _ui_labels(value):
    if not isinstance(value,str):
        return []
    text = value.strip().lower().replace('…','...')
    labels = []
    if text in {'cancel','取消'}: labels.append('Cancel')
    if text in {'replace','替换'}: labels.append('Replace')
    if text in {'save','保存'}: labels.append('Save')
    if text in {'save as','save as...','另存为','另存为...'}: labels.append('Save As')
    if text in {'close','close window','关闭','关闭窗口'}: labels.append('Close')
    if text in {'go to folder','前往文件夹'}: labels.append('Go to Folder')
    if text in {'new finder window','new window','新建 finder 窗口','新建窗口'}: labels.append('New Finder Window')
    if text in {'open','打开'}: labels.append('Open')
    if text in {'delete','delete...','删除','删除...'}: labels.append('Delete')
    return labels


def _strings(value):
    result = []
    if isinstance(value,str):
        result.append(value)
    elif isinstance(value,dict):
        for item in value.values():
            result.extend(_strings(item))
    elif isinstance(value,list):
        for item in value:
            result.extend(_strings(item))
    return result


def _script_facts(request):
    script = normalize_script(request.get('script'))
    gestures = []
    if script == 'macos: keys':
        args = request.get('args')
        options = args[0] if isinstance(args,list) and args and isinstance(args[0],dict) else {}
        for item in options.get('keys',[]):
            if not isinstance(item,dict) or not isinstance(item.get('key'),str):
                continue
            flags = item.get('modifierFlags',0)
            if not isinstance(flags,int) or isinstance(flags,bool):
                continue
            key = item['key'].lower()
            command, shift = bool(flags & (1 << 4)), bool(flags & (1 << 1))
            if command and key == 'n': gestures.append('newWindow')
            if command and shift and key == 'g': gestures.append('goToFolder')
            if command and shift and key == 's': gestures.append('saveAs')
            if command and not shift and key == 's': gestures.append('save')
            if command and key == 'w': gestures.append('close')
            if command and key == 'q': gestures.append('quit')
            if command and key == 'o': gestures.append('open')
        gestures = list(dict.fromkeys(gestures))
    if script == 'macos: click': gestures.append('clickScript')
    if script == 'macos: doubleclick': gestures.extend(['clickScript','doubleClick'])
    if script == 'macos: deeplink': gestures.append('deepLink')
    if script == 'macos: activateapp': gestures.append('activateApp')
    if script == 'macos: terminateapp': gestures.append('terminateApp')
    if script == 'macos: queryappstate': gestures.append('queryAppState')
    return script, gestures


def _arg_element_id(request):
    for item in _strings(request.get('args')):
        if re.fullmatch(r'[0-9A-Fa-f-]{20,}', item):
            return item
    return None


def _attribute_name(path):
    match = re.search(r'/attribute/([^/]+)$', path)
    if match:
        return match.group(1) if match.group(1) in ATTRIBUTE_ALLOWLIST else '$OTHER'
    for name in ('selected','displayed','enabled','text','name'):
        if path.endswith('/' + name):
            return name
    return None


def _action(path, method, request):
    script, gestures = _script_facts(request)
    kind = None
    if path.endswith('/click'):
        kind = 'click'
    elif path.endswith('/value'):
        kind = 'value'
    elif path.endswith('/clear'):
        kind = 'clear'
    elif re.search(r'/execute(?:/sync)?$', path):
        kind = 'execute'
    elif path.endswith('/window') and method == 'POST':
        kind = 'window-switch'
    elif path.endswith('/window') and method == 'DELETE':
        kind = 'window-close'
    target = None
    match = re.match(r'^/session/[^/]+/element/([^/]+)', path)
    if match:
        target = match.group(1)
    if target is None:
        target = _arg_element_id(request)
    return {'kind':kind,'target':target,'script':script,'gestures':gestures}


def _element_from_path(path):
    match = re.match(r'^/session/[^/]+/element/([^/]+)', path)
    return match.group(1) if match else None


def _parent_from_path(path):
    match = re.match(r'^/session/[^/]+/element/([^/]+)/(?:element|elements)(?:/|$)', path)
    return match.group(1) if match else None


def build_protocol(txns, expected):
    records = []
    for index,txn in enumerate(txns):
        if not isinstance(txn,dict):
            continue
        method = txn.get('method')
        path = txn.get('path')
        if not isinstance(method,str) or not isinstance(path,str):
            continue
        request = txn.get('request') if isinstance(txn.get('request'),dict) else {}
        value = returned(txn)
        status = txn.get('status')
        session_raw = session_id_of(path)
        if not session_raw and path == '/session' and isinstance(txn.get('sessionCreated'),str):
            session_raw = txn['sessionCreated']
        element = _element_from_path(path)
        parent = _parent_from_path(path)
        action = _action(path,method,request)
        record = {
            'index':index,
            'method':method,
            'pathKind':_path_kind(path),
            'status':status,
            'startedAt':txn.get('startedAt'),
            'completedAt':txn.get('completedAt'),
            'sessionSha256':digest(session_raw) if session_raw else None,
            'sessionCreatedSha256':digest(txn['sessionCreated']) if isinstance(txn.get('sessionCreated'),str) else None,
            'elementSha256':digest(element) if element else None,
            'parentElementSha256':digest(parent) if parent else None,
            'responseElementSha256s':[digest(item) for item in _response_element_ids(value)],
            'windowQueryRequest':bool(path.endswith(('/elements','/element')) and 'XCUIElementTypeWindow' in json.dumps(request,ensure_ascii=False)),
            'windowQuery':bool(path.endswith(('/elements','/element')) and 'XCUIElementTypeWindow' in json.dumps(request,ensure_ascii=False)),
            'attributeName':_attribute_name(path),
            'requestMatches':_matches(request,expected),
            'responseMatches':_matches(value,expected),
            'responseSha256':digest(json.dumps(value,ensure_ascii=False)) if isinstance(value,(str,int,float,bool)) or value is None else None,
            'responseTextSha256':digest(value) if isinstance(value,str) else None,
            'uiLabels':_ui_labels(value),
            'selectedValue':_scalar_bool(value) if (_attribute_name(path) == 'selected' or path.endswith('/selected')) else None,
            'actionKind':action['kind'],
            'actionTargetElementSha256':digest(action['target']) if action['target'] else None,
            'script':action['script'] if action['script'] in SAFE_SCRIPTS else None,
            'gestures':list(action['gestures']),
            'createIdentity':None,
        }
        if record['windowQuery'] and status == 200:
            record['windowQuery'] = True
        else:
            record['windowQuery'] = False
        if path == '/session' and method == 'POST':
            caps = json.dumps(request,ensure_ascii=False)
            result = json.dumps(value,ensure_ascii=False)
            request_bundle = next((bundle for bundle in (TEXTEDIT,FINDER) if bundle in caps),None)
            response_bundle = next((bundle for bundle in (TEXTEDIT,FINDER) if bundle in result),None)
            record['createIdentity'] = {
                'requestMac2':bool(request.get('capabilities',{}).get('alwaysMatch',{}).get('appium:automationName') == 'Mac2' or 'Mac2' in caps),
                'responseMac2':'Mac2' in result,
                'requestBundle':request_bundle,
                'responseBundle':response_bundle,
            }
        if isinstance(value,list):
            record['returnedCount'] = len(value)
        records.append(record)
    labels = {}
    match_keys = {}
    for record in records:
        if record['status'] == 200 and record.get('elementSha256'):
            labels.setdefault(record['elementSha256'],set()).update(record['uiLabels'])
            match_keys.setdefault(record['elementSha256'],set()).update(record['responseMatches'])
    for record in records:
        target = record.get('actionTargetElementSha256')
        if not target or record['status'] != 200:
            continue
        for label in labels.get(target,set()):
            if label == 'Cancel': record['gestures'].append('cancel')
            elif label == 'Replace': record['gestures'].append('replace')
            elif label == 'Save': record['gestures'].append('save')
            elif label == 'Save As': record['gestures'].append('saveAs')
            elif label == 'Close': record['gestures'].append('close')
            elif label == 'Go to Folder': record['gestures'].append('goToFolder')
            elif label == 'New Finder Window': record['gestures'].append('newWindow')
            elif label == 'Open': record['gestures'].append('open')
            elif label == 'Delete': record['gestures'].append('delete')
        record['actionTargetMatches'] = sorted(match_keys.get(target,set()))
    return records


def parse_executions(native):
    calls = native.get('calls')
    if not isinstance(calls,list):
        return None
    executions = []
    previous_count = None
    previous_end = None
    for raw in calls:
        if not isinstance(raw,dict):
            return None
        if raw.get('mcpToolName') != 'python_exec':
            continue
        if raw.get('mcpConfigServerName') != 'amkernel' and raw.get('toolName') != 'amkernel-python_exec':
            return None
        status = raw.get('status')
        kernel = raw.get('kernelState')
        success = raw.get('success')
        count = raw.get('executionCount')
        window = _window(raw)
        if status not in {'completed','failed'} or kernel != 'alive':
            return None
        if not isinstance(success,bool):
            return None
        if not isinstance(count,int) or isinstance(count,bool) or count < 1:
            return None
        if window is None:
            return None
        if previous_count is not None and count <= previous_count:
            return None
        if previous_end is not None and window[0] < previous_end:
            return None
        executions.append({
            'index':len(executions),
            'callSha256':raw.get('callIdSha256'),
            'status':status,
            'success':success,
            'kernelState':kernel,
            'executionCount':count,
            'window':window,
            'errorType':raw.get('errorType'),
            'codeSha256':raw.get('codeSha256'),
            'argumentsSha256':raw.get('argumentsSha256'),
        })
        previous_count = count
        previous_end = window[1]
    return executions or None


def bind_executions(records, executions):
    if executions is None:
        return
    for record in records:
        window = _window(record)
        if window is None:
            continue
        matches = [execution for execution in executions if _inside(window,execution['window'])]
        if len(matches) != 1:
            continue
        execution = matches[0]
        record['executionIndex'] = execution['index']
        record['mcpCallSha256'] = execution['callSha256']
        record['executionStatus'] = execution['status']
        record['executionSuccess'] = execution['success']
        record['executionKernelState'] = execution['kernelState']


def successful_execution(record, executions):
    index = record.get('executionIndex')
    if executions is None or not isinstance(index,int) or not (0 <= index < len(executions)):
        return False
    execution = executions[index]
    return execution['status'] == 'completed' and execution['success'] is True and execution['kernelState'] == 'alive'


def failed_execution(record, executions):
    index = record.get('executionIndex')
    if executions is None or not isinstance(index,int) or not (0 <= index < len(executions)):
        return False
    execution = executions[index]
    return execution['status'] == 'failed' and execution['kernelState'] == 'alive'


def _ancestry(records):
    parent = {}
    for record in records:
        if record.get('parentElementSha256'):
            for child in record.get('responseElementSha256s',[]):
                parent[child] = record['parentElementSha256']
    return parent


def _window_under(element, window_ids, parent):
    current = element
    for _ in range(16):
        if current is None:
            return None
        if current in window_ids:
            return current
        current = parent.get(current)
    return None


def window_epochs(records):
    parent = _ancestry(records)
    epochs = []
    current = None
    for record in records:
        if record.get('windowQuery') and record.get('status') == 200:
            current = {
                'index':record['index'],
                'sessionSha256':record.get('sessionSha256'),
                'ids':set(record.get('responseElementSha256s',[])),
                'titles':{},
                'titleSha':{},
                'contents':{},
                'contentIndex':{},
            }
            for window in current['ids']:
                current['titles'][window] = set()
                current['titleSha'][window] = set()
                current['contents'][window] = set()
                current['contentIndex'][window] = {}
            epochs.append(current)
            continue
        if current is None or record.get('sessionSha256') != current['sessionSha256']:
            continue
        if record.get('status') != 200:
            continue
        window = _window_under(record.get('elementSha256'),current['ids'],parent)
        if window is None:
            continue
        if record.get('attributeName') in TITLE_ATTRIBUTES and record.get('responseTextSha256'):
            current['titles'][window].update(record.get('responseMatches',[]))
            current['titleSha'][window].add(record['responseTextSha256'])
        for key in record.get('responseMatches',[]):
            current['contents'][window].add(key)
            current['contentIndex'][window].setdefault(key,[]).append(record['index'])
    return epochs, parent


def _pairs(epochs, title_key, content_key):
    result = []
    for epoch in epochs:
        for window in epoch['ids']:
            if title_key in epoch['titles'].get(window,set()) and content_key in epoch['contents'].get(window,set()):
                result.append((epoch,window))
    return result


def _content_indices(epoch, window, key):
    return epoch['contentIndex'].get(window,{}).get(key,[])


def _is_click(record):
    return record.get('actionKind') == 'click' or 'clickScript' in record.get('gestures',[])


def _window_clicks(records, window, parent, executions, after_index=None):
    result = []
    for record in records:
        if after_index is not None and record['index'] <= after_index:
            continue
        if record.get('status') != 200 or not _is_click(record):
            continue
        if record.get('actionTargetElementSha256') != window:
            continue
        if successful_execution(record,executions):
            result.append(record)
    return result


def _ancestor_chain(element, parent):
    chain = []
    seen = set()
    current = element
    while current and current not in seen:
        chain.append(current)
        seen.add(current)
        current = parent.get(current)
    return chain


def _observed_dialog(name_obs, replace_obs, cancel_obs, window_ids, parent):
    elements = [record.get('elementSha256') for record in (name_obs,replace_obs,cancel_obs) if record]
    if len(elements) != 3 or any(element is None for element in elements):
        return None
    chains = [set(_ancestor_chain(element,parent)) for element in elements]
    common = set.intersection(*chains)
    for candidate in sorted(common):
        if candidate not in window_ids and candidate not in elements:
            return candidate
    return None


def _m1_ordered_sequence(records, target_epoch, target_window, distractor_epoch, distractor_window, parent, executions):
    target_indices = _content_indices(target_epoch,target_window,'initialTargetText')
    distractor_indices = _content_indices(distractor_epoch,distractor_window,'distractorText')
    target_titles = _content_indices(target_epoch,target_window,'targetName')
    distractor_titles = _content_indices(distractor_epoch,distractor_window,'distractorName')
    if not target_indices or not distractor_indices or not target_titles or not distractor_titles:
        return None
    target_clicks = _window_clicks(records,target_window,parent,executions,target_epoch['index'])
    distractor_clicks = _window_clicks(records,distractor_window,parent,executions,distractor_epoch['index'])
    for first_click in target_clicks:
        if min(target_titles) >= first_click['index']:
            continue
        for first_read in [index for index in target_indices if index > first_click['index']]:
            for distractor_click in distractor_clicks:
                if distractor_click['index'] <= first_read or min(distractor_titles) >= distractor_click['index']:
                    continue
                for distractor_read in [index for index in distractor_indices if index > distractor_click['index']]:
                    for second_click in target_clicks:
                        if second_click['index'] <= distractor_read:
                            continue
                        for second_read in [index for index in target_indices if index > second_click['index']]:
                            return {
                                'firstClick':first_click,
                                'firstRead':first_read,
                                'distractorClick':distractor_click,
                                'distractorRead':distractor_read,
                                'secondClick':second_click,
                                'secondRead':second_read,
                            }
    return None


def _ui_reopen_action(records, start_index, parent, executions, target_name, distractor_name):
    path_entry = None
    for record in records:
        if record['index'] <= start_index or record.get('status') != 200 or not successful_execution(record,executions):
            continue
        gestures = record.get('gestures',[])
        requests = record.get('requestMatches',[])
        targets = record.get('actionTargetMatches',[])
        if 'deepLink' in gestures and distractor_name not in requests and (target_name in requests or 'sourceUri' in requests):
            return record, None
        if ('doubleClick' in gestures and target_name in targets and distractor_name not in targets
                and target_name in requests and distractor_name not in requests):
            return record, None
        if (path_entry is None and record.get('actionKind') in {'value','execute'}
                and target_name in requests and distractor_name not in requests):
            path_entry = record
            continue
        if path_entry and record['index'] > path_entry['index'] and _is_click(record) and 'open' in gestures:
            return record, path_entry
    return None, None


def _request_has_marker(record, marker):
    return marker in record.get('requestMatches',[])


def _execution_payloads(executions, native, payloads):
    calls = native.get('calls')
    if not isinstance(calls,list) or not isinstance(payloads,list):
        return None
    payload_calls = [call for call in calls if isinstance(call,dict) and call.get('mcpToolName') == 'python_exec' and 'status' in call]
    if len(payload_calls) != len(executions) or len(payloads) != len(payload_calls):
        return None
    return {execution['index']:payload for execution,payload in zip(executions,payloads)}




def _quit_failure_facts(payload, owned_sha256):
    error = payload.get('error') if isinstance(payload,dict) else None
    error = error if isinstance(error,dict) else {}
    lines = error.get('traceback')
    lines = lines if isinstance(lines,list) and all(isinstance(line,str) for line in lines) else []
    quit_frame = any(re.search(r'''File ["'][^"']*/(?:selenium|appium)/webdriver/(?:remote/)?webdriver\.py["'], line \d+, in quit\b''',line) for line in lines)
    message = error.get('message') if isinstance(error.get('message'),str) else ''
    text = '\n'.join([message,*lines])
    owned_url = bool(owned_sha256) and any(
        digest(match.group(1)) == owned_sha256
        for match in re.finditer(r'''/session/([0-9A-Za-z-]{8,})/?(?=[\s"'<>):]|$)''',text)
    )
    return {'quitFrameObserved':quit_frame,'ownedRootSessionUrlObserved':owned_url,'errorSha256':digest(json.dumps(error,sort_keys=True)) if error else None}


def _is_typing(record, marker):
    return record.get('status') == 200 and _request_has_marker(record,marker) and record.get('actionKind') in {'value','execute'} and 'save' not in record.get('gestures',[]) and 'saveAs' not in record.get('gestures',[])


def _is_save(record):
    return record.get('status') == 200 and ('save' in record.get('gestures',[]) or 'saveAs' in record.get('gestures',[]))


def _marker_response(records, marker, start_index, executions, session=None):
    for record in records:
        if record['index'] <= start_index or record.get('method') != 'GET' or record.get('status') != 200:
            continue
        if marker not in record.get('responseMatches',[]):
            continue
        if session is not None and record.get('sessionSha256') != session:
            continue
        if successful_execution(record,executions):
            return record
    return None


def _create_records(records):
    return [record for record in records if record.get('createIdentity') and record.get('status') == 200 and record.get('createIdentity',{}).get('requestBundle')]


def _finder_ownership(records, ownership, expected):
    result = {
        'receiptPresent':ownership.get('valid') is True,
        'receiptValid':False,
        'baselineObserved':False,
        'newWindowObserved':False,
        'ownedWindowBound':False,
        'navigationBound':False,
        'closedOwnedWindow':False,
        'preexistingWindowsPreserved':False,
        'noPreexistingWindowClosed':False,
        'noAmbiguousOwnership':False,
    }
    finder_creates = [record for record in _create_records(records) if record['createIdentity']['requestBundle'] == FINDER]
    if not finder_creates or ownership.get('valid') is not True:
        return result
    finder_session = finder_creates[0].get('sessionCreatedSha256')
    if not finder_session or ownership.get('sessionSha256') != finder_session:
        return result
    epochs, _parent = window_epochs(records)
    epochs = [epoch for epoch in epochs if epoch.get('sessionSha256') == finder_session]
    new_gesture = next((record for record in records if record.get('status') == 200 and 'newWindow' in record.get('gestures',[]) and record.get('sessionSha256') == finder_session),None)
    if not epochs or new_gesture is None:
        return result
    baseline_epochs = [epoch for epoch in epochs if epoch['index'] < new_gesture['index']]
    if not baseline_epochs:
        return result
    baseline = baseline_epochs[-1]
    baseline_titles = set()
    for window in baseline['ids']:
        baseline_titles.update(baseline['titleSha'].get(window,set()))
    if len(baseline_titles) != len(baseline['ids']):
        return result
    result['baselineObserved'] = True
    receipt_baseline = set(ownership.get('baselineWindowSha256s',[]))
    if ownership.get('baselineWindowCount') != len(baseline['ids']) or receipt_baseline != baseline_titles:
        return result
    def epoch_titles(epoch):
        titles = set()
        for window in epoch['ids']:
            titles.update(epoch['titleSha'].get(window,set()))
        return titles

    post_epochs = [epoch for epoch in epochs if epoch['index'] > new_gesture['index']]
    if not post_epochs:
        return result
    creation_epochs = [epoch for epoch in post_epochs if len(epoch['ids']) == len(baseline['ids']) + 1 and baseline_titles <= epoch_titles(epoch)]
    if not creation_epochs:
        return result
    creation = creation_epochs[0]
    result['newWindowObserved'] = True
    owned = ownership.get('ownedWindowSha256')
    owned_epochs = [epoch for epoch in post_epochs if epoch['index'] >= creation['index'] and any(owned in epoch['titleSha'].get(window,set()) for window in epoch['ids'])]
    if not owned_epochs or owned in baseline_titles:
        return result
    result['ownedWindowBound'] = True
    target_tokens = {'targetFolderName','targetDir','targetUri'}
    navigation_epoch = None
    for epoch in owned_epochs:
        if len(epoch['ids']) != len(baseline['ids']) + 1 or not baseline_titles <= epoch_titles(epoch):
            continue
        for window in epoch['ids']:
            if owned in epoch['titleSha'].get(window,set()) and target_tokens.intersection(epoch['titles'].get(window,set()) | epoch['contents'].get(window,set())):
                navigation_epoch = epoch
                break
        if navigation_epoch is not None:
            break
    if navigation_epoch is None:
        return result
    result['navigationBound'] = True
    close_gesture = next((record for record in records if record.get('index') > navigation_epoch['index'] and record.get('status') == 200 and 'close' in record.get('gestures',[]) and record.get('sessionSha256') == finder_session),None)
    if close_gesture is None:
        return result
    final_epochs = [epoch for epoch in epochs if epoch['index'] > close_gesture['index']]
    if not final_epochs:
        return result
    final = final_epochs[-1]
    final_titles = epoch_titles(final)
    result['closedOwnedWindow'] = len(final['ids']) == len(baseline['ids']) and baseline_titles <= final_titles and owned not in final_titles
    result['preexistingWindowsPreserved'] = baseline_titles <= final_titles
    result['noPreexistingWindowClosed'] = len(final['ids']) >= len(baseline['ids']) and baseline_titles <= final_titles
    result['noAmbiguousOwnership'] = len(baseline['ids']) == len(baseline_titles) and owned not in baseline_titles
    result['receiptValid'] = all(result[key] for key in ('baselineObserved','newWindowObserved','ownedWindowBound','navigationBound','closedOwnedWindow','preexistingWindowsPreserved','noPreexistingWindowClosed','noAmbiguousOwnership'))
    return result


def scenario_checks(scenario, records, controls, executions, native, marker, payloads=None):
    checks = {}
    if scenario == 'M1':
        epochs, parent = window_epochs(records)
        target = _pairs(epochs,'targetName','initialTargetText')
        distractor = _pairs(epochs,'distractorName','distractorText')
        common = []
        for target_epoch,target_window in target:
            for distractor_epoch,distractor_window in distractor:
                if target_window != distractor_window:
                    common.append((target_epoch,target_window,distractor_epoch,distractor_window))
        sequence = None
        for target_epoch,target_window,distractor_epoch,distractor_window in common:
            sequence = _m1_ordered_sequence(records,target_epoch,target_window,distractor_epoch,distractor_window,parent,executions)
            if sequence:
                break
        checks['distinctWindowsObserved'] = bool(common)
        checks['targetThenDistractorThenTarget'] = sequence is not None
        checks['targetSelectedByObservedName'] = sequence is not None
        checks['distractorSelectedByObservedName'] = sequence is not None
        checks['targetReselectedByObservedName'] = sequence is not None
        checks['noMarkerTyped'] = not any(marker in record.get('requestMatches',[]) and record.get('actionKind') in {'value','execute'} for record in records)
    if scenario == 'M2':
        epochs, parent = window_epochs(records)
        initial = _pairs(epochs,'targetName','initialTargetText')
        start = min((epoch['index'] for epoch,window in initial),default=-1)
        typing = next((record for record in records if record['index'] > start and _is_typing(record,marker) and successful_execution(record,executions)),None)
        save = next((record for record in records if typing and record['index'] > typing['index'] and _is_save(record) and successful_execution(record,executions)),None)
        saved_pairs = [(epoch,window) for epoch,window in _pairs(epochs,'targetName','marker') if save and any(index > save['index'] for index in _content_indices(epoch,window,'marker'))]
        saved_pair = saved_pairs[0] if saved_pairs else None
        saved = _marker_response(records,marker,save['index'] if save else 10**9,executions)
        saved_indices = [index for index in _content_indices(*saved_pair,'marker') if index > save['index']] if saved_pair else []
        close = None
        absent_epoch = None
        if saved_pair and saved_indices:
            saved_index = min(saved_indices)
            for candidate in records:
                if candidate['index'] <= saved_index or 'close' not in candidate.get('gestures',[]) or not successful_execution(candidate,executions):
                    continue
                after = [epoch for epoch in epochs if epoch['index'] > candidate['index'] and saved_pair[1] not in epoch['ids'] and all(epoch['titleSha'].get(window) for window in epoch['ids']) and not any('targetName' in epoch['titles'].get(window,set()) for window in epoch['ids']) and any('distractorName' in epoch['titles'].get(window,set()) for window in epoch['ids'])]
                if after:
                    close = candidate
                    absent_epoch = after[0]
                    break
        reopen_action = None
        if absent_epoch:
            reopen_action, _ = _ui_reopen_action(records,absent_epoch['index'],parent,executions,'targetName','distractorName')
        reopened_pairs = [(epoch,window) for epoch,window in _pairs(epochs,'targetName','marker') if close and reopen_action and epoch['index'] > max(close['index'],reopen_action['index'])]
        reopened = _marker_response(records,marker,reopen_action['index'] if reopen_action else 10**9,executions)
        checks['initialTargetObserved'] = bool(initial)
        checks['markerTypedThroughUi'] = typing is not None
        checks['savedTargetObservedBeforeClose'] = bool(save and saved and saved_pair and saved_indices and close and saved['index'] < close['index'] and min(saved_indices) < close['index'])
        checks['targetClosed'] = bool(close and absent_epoch and saved and saved_indices)
        checks['reopenedThroughUi'] = bool(reopen_action and reopened_pairs)
        checks['markerReadBackAfterReopen'] = bool(reopened_pairs and reopened)
        checks['noRetypeAfterClose'] = not any(close and record['index'] > close['index'] and _is_typing(record,marker) for record in records)
        checks['markerReadBackResponseOnly'] = bool(reopened and marker in reopened.get('responseMatches',[]))
    if scenario == 'M3':
        epochs, parent = window_epochs(records)
        window_ids = set().union(*(epoch['ids'] for epoch in epochs)) if epochs else set()
        target = _pairs(epochs,'targetName','initialTargetText')
        start = min((epoch['index'] for epoch,window in target),default=-1)
        save_as = next((record for record in records if record['index'] > start and ('saveAs' in record.get('gestures',[])) and successful_execution(record,executions)),None)
        name_obs = next((record for record in records if save_as and record['index'] > save_as['index'] and 'existingName' in record.get('responseMatches',[]) and successful_execution(record,executions)),None)
        replace_obs = next((record for record in records if name_obs and record['index'] > name_obs['index'] and 'Replace' in record.get('uiLabels',[]) and successful_execution(record,executions)),None)
        cancel_obs = next((record for record in records if replace_obs and record['index'] > replace_obs['index'] and 'Cancel' in record.get('uiLabels',[]) and successful_execution(record,executions)),None)
        cancel_elements = set(cancel_obs.get('responseElementSha256s',[])) if cancel_obs else set()
        if cancel_obs and cancel_obs.get('elementSha256'):
            cancel_elements.add(cancel_obs['elementSha256'])
        cancel_click = next((record for record in records if cancel_obs and record['index'] > cancel_obs['index'] and _is_click(record) and record.get('actionTargetElementSha256') in cancel_elements and successful_execution(record,executions)),None)
        replace_click = any(record['index'] > start and _is_click(record) and 'replace' in record.get('gestures',[]) for record in records)
        dialog = _observed_dialog(name_obs,replace_obs,cancel_obs,window_ids,parent)
        source_return = next((record for record in records if cancel_click and record['index'] > cancel_click['index'] and 'initialTargetText' in record.get('responseMatches',[]) and successful_execution(record,executions)),None)
        source_pairs = [(epoch,window) for epoch,window in target if cancel_click and any(index > cancel_click['index'] for index in _content_indices(epoch,window,'initialTargetText'))]
        checks['initialTargetObserved'] = bool(target)
        checks['saveAsUiObserved'] = save_as is not None
        checks['collisionDialogReached'] = bool(name_obs and replace_obs and cancel_obs)
        checks['cancelBoundToCollisionDialog'] = bool(dialog and cancel_click and not replace_click)
        checks['sourceReturnAfterCancel'] = bool(source_return and source_pairs)
        checks['destinationUnchanged'] = True
    if scenario == 'M4':
        mutation = next((item for item in controls if item.get('action') == 'mutate' and item.get('succeeded')),None)
        post = [record for record in records if mutation and _after(record.get('startedAt'),mutation.get('completedAt'))]
        fresh = {}
        for record in post:
            if record.get('status') == 200 and not record.get('windowQuery') and successful_execution(record,executions):
                for element in record.get('responseElementSha256s',[]):
                    fresh.setdefault(element,record['index'])
        selected = None
        label = None
        folder = None
        not_distractor = False
        for record in post:
            if record.get('status') != 200 or record.get('attributeName') != 'selected' or record.get('selectedValue') is not True or not successful_execution(record,executions):
                continue
            element = record.get('elementSha256')
            if not element or element not in fresh or fresh[element] >= record['index']:
                continue
            label_record = next((candidate for candidate in post if candidate.get('elementSha256') == element and candidate.get('status') == 200 and 'targetName' in candidate.get('responseMatches',[]) and successful_execution(candidate,executions)),None)
            epochs, parent = window_epochs(records)
            window = None
            for epoch in epochs:
                if epoch['index'] <= record['index']:
                    continue
                candidate_window = _window_under(element,epoch['ids'],parent)
                if candidate_window is not None:
                    window = (epoch,candidate_window)
                    break
            folder_record = None
            if window is not None:
                epoch,window_id = window
                folder_record = next((candidate for candidate in post if candidate['index'] >= epoch['index'] and candidate.get('status') == 200 and ('targetFolderName' in candidate.get('responseMatches',[]) or 'targetDir' in candidate.get('responseMatches',[]) or 'targetUri' in candidate.get('responseMatches',[])) and _window_under(candidate.get('elementSha256'),{window_id},parent) == window_id and successful_execution(candidate,executions)),None)
            if label_record and folder_record:
                selected = record; label = label_record; folder = folder_record
                not_distractor = not any('distractorFolderName' in epoch['contents'].get(window_id,set()) or 'distractorDir' in epoch['contents'].get(window_id,set()) for epoch,window_id in [window])
                break
        checks['fixtureMutationObserved'] = mutation is not None
        checks['postMutationQuerySucceeded'] = bool(fresh)
        checks['selectedFreshElement'] = selected is not None
        checks['selectedExactRelativeTarget'] = bool(selected and label and folder)
        checks['selectedNotDistractor'] = bool(checks['selectedExactRelativeTarget'] and not_distractor)
        checks['noTextEditOpened'] = not any(record.get('createIdentity',{}).get('requestBundle') == TEXTEDIT for record in _create_records(records))
    if scenario == 'M5':
        finder_creates = [record for record in _create_records(records) if record.get('createIdentity',{}).get('requestBundle') == FINDER]
        textedit_creates = [record for record in _create_records(records) if record.get('createIdentity',{}).get('requestBundle') == TEXTEDIT]
        finder_session = finder_creates[0].get('sessionCreatedSha256') if finder_creates else None
        epochs, parent = window_epochs(records)
        target_windows = set()
        for epoch in epochs:
            if finder_session is None or epoch.get('sessionSha256') != finder_session:
                continue
            for window in epoch['ids']:
                if 'targetDir' in epoch['titles'].get(window,set()) or 'targetFolderName' in epoch['titles'].get(window,set()):
                    target_windows.add(window)
        observation = None
        for record in records:
            if record.get('status') != 200 or not successful_execution(record,executions) or record.get('sessionSha256') != finder_session:
                continue
            if 'targetName' not in record.get('responseMatches',[]):
                continue
            candidates = set(record.get('responseElementSha256s',[]))
            if record.get('elementSha256'):
                candidates.add(record['elementSha256'])
            bound = {element for element in candidates if _window_under(element,target_windows,parent) is not None}
            if bound:
                observation = (record,bound)
                break
        open_action = None
        if observation:
            obs_record,file_elements = observation
            open_action = next((record for record in records if record['index'] > obs_record['index'] and record.get('status') == 200 and record.get('sessionSha256') == finder_session and successful_execution(record,executions) and 'doubleClick' in record.get('gestures',[]) and record.get('actionTargetElementSha256') in file_elements),None)
        textedit_create = next((record for record in textedit_creates if open_action and record['index'] > open_action['index'] and successful_execution(record,executions)),None)
        textedit_pairs = []
        for epoch in epochs:
            if textedit_create is None or epoch['index'] <= textedit_create['index'] or epoch.get('sessionSha256') != textedit_create.get('sessionCreatedSha256'):
                continue
            for window in epoch['ids']:
                if 'targetName' in epoch['titles'].get(window,set()) and 'listTargetText' in epoch['contents'].get(window,set()):
                    textedit_pairs.append((epoch,window))
        checks['finderTargetObserved'] = observation is not None
        checks['finderOpenActionBound'] = open_action is not None
        checks['texteditDestinationCreated'] = textedit_create is not None
        checks['texteditWindowMatched'] = bool(textedit_pairs)
        checks['texteditContentMatched'] = bool(textedit_pairs)
        checks['twoActualAppIdentities'] = {record['createIdentity']['requestBundle'] for record in _create_records(records)} >= {FINDER,TEXTEDIT}
    if scenario == 'M6':
        creates = _create_records(records)
        interrupt = next((item for item in controls if item.get('action') == 'interrupt' and item.get('succeeded')),None)
        first = creates[0] if len(creates) >= 1 else None
        second = creates[1] if len(creates) >= 2 else None
        pre = [record for record in records if interrupt and _utc(record.get('startedAt')) and _utc(interrupt.get('completedAt')) and _utc(record['startedAt']) < _utc(interrupt['completedAt'])]
        typing = next((record for record in pre if _is_typing(record,marker) and successful_execution(record,executions)),None)
        save = next((record for record in pre if typing and record['index'] > typing['index'] and _is_save(record) and successful_execution(record,executions)),None)
        saved = next((record for record in pre if save and record['index'] > save['index'] and marker in record.get('responseMatches',[]) and successful_execution(record,executions)),None)
        stale = None
        for record in records:
            if interrupt and record.get('sessionSha256') == (first.get('sessionCreatedSha256') if first else None) and _after(record.get('startedAt'),interrupt.get('completedAt')) and record.get('status') is not None and record.get('status') != 200 and record.get('method') in {'GET','POST'} and (record.get('windowQueryRequest') or record.get('attributeName')):
                stale = record
                break
        stale_ok = False
        if stale and failed_execution(stale,executions):
            execution = executions[stale['executionIndex']]
            stale_ok = _after(execution['window'][0].isoformat(),interrupt.get('completedAt'))
        replacement = None
        if stale and len(creates) >= 2:
            replacement = next((record for record in creates[1:] if _after(record.get('startedAt'),stale.get('completedAt')) and record.get('sessionCreatedSha256') != (first.get('sessionCreatedSha256') if first else None)),None)
        readback = None
        if replacement:
            readback = next((record for record in records if record['index'] > replacement['index'] and record.get('sessionSha256') == replacement.get('sessionCreatedSha256') and record.get('method') == 'GET' and marker in record.get('responseMatches',[]) and successful_execution(record,executions)),None)
        after_interrupt = [record for record in records if interrupt and _after(record.get('startedAt'),interrupt.get('completedAt'))]
        checks['interruptedSessionIdentity'] = bool(first and interrupt and interrupt.get('sessionSha256') == first.get('sessionCreatedSha256'))
        checks['savedBeforeInterrupt'] = bool(typing and save and saved)
        checks['markerPersistedBeforeInterrupt'] = bool(interrupt and interrupt.get('targetMarkerPersisted') is True)
        checks['staleSessionFailureObserved'] = stale_ok
        checks['replacementSessionAfterFailure'] = replacement is not None
        checks['replacementMarkerReadback'] = readback is not None
        checks['noRetypeOrResaveAfterInterrupt'] = not any(_is_typing(record,marker) or 'save' in record.get('gestures',[]) or 'saveAs' in record.get('gestures',[]) for record in after_interrupt)
        checks['twoOwnedSessions'] = len(creates) == 2
    if scenario == 'M7':
        fault = next((item for item in controls if item.get('action') == 'stop-server' and item.get('succeeded')),None)
        creates = _create_records(records)
        pre = [record for record in records if fault and _utc(record.get('startedAt')) and _utc(fault.get('completedAt')) and _utc(record['startedAt']) < _utc(fault['completedAt'])]
        typing = next((record for record in pre if _is_typing(record,marker) and successful_execution(record,executions)),None)
        save = next((record for record in pre if typing and record['index'] > typing['index'] and _is_save(record) and successful_execution(record,executions)),None)
        saved = next((record for record in pre if save and record['index'] > save['index'] and marker in record.get('responseMatches',[]) and successful_execution(record,executions)),None)
        post = [execution for execution in (executions or []) if fault and _after(execution['window'][0].isoformat(),fault.get('completedAt'))]
        failed = [execution for execution in post if execution['status'] == 'failed' and execution['kernelState'] == 'alive' and str(execution.get('errorType','')).rsplit('.',1)[-1] in NETWORK_ERROR_TYPES]
        successes = [execution for execution in post if execution['status'] == 'completed' and execution['success'] is True]
        payload_map = _execution_payloads(executions or [],native,payloads or [])
        quit_attempt = None
        if len(failed) == 1 and post and failed[0] is post[-1]:
            candidate = failed[0]
            payload = payload_map.get(candidate['index']) if payload_map else None
            facts = _quit_failure_facts(payload,fault.get('ownedSessionSha256'))
            native['quitFailureEvidence'] = dict(facts,executionCount=candidate['executionCount'],callSha256=candidate.get('callSha256'))
            if facts['quitFrameObserved'] and facts['ownedRootSessionUrlObserved']:
                quit_attempt = candidate
        checks['markerSavedBeforeFault'] = bool(typing and save and saved)
        checks['restorationVerifiedBeforeFault'] = bool(fault and fault.get('restorationVerified') is True and fault.get('listingCountBeforeStop') == 1 and fault.get('ownedSessionSha256') is not None and len(creates) == 1)
        checks['controlledOwnedServerStop'] = fault is not None
        checks['exactlyOnePostStopFailedQuit'] = quit_attempt is not None and len(failed) == 1 and len(post) == len(failed) + len(successes)
        checks['postStopOnlyOneControlWait'] = len(successes) <= 1 and (not successes or (quit_attempt is not None and successes[0]['index'] < quit_attempt['index']))
        checks['postStopNoSuccessAfterQuit'] = quit_attempt is not None and not any(execution['index'] > quit_attempt['index'] for execution in successes)
    return checks


def fixture_checks(scenario, initial_files, after_files, inserted_expected):
    if not isinstance(initial_files,dict) or not isinstance(after_files,dict):
        return {'fixtureStateObserved':False}
    initial_names = set(initial_files)
    after_names = set(after_files)
    checks = {'fixtureStateObserved':True}
    source_name = 'AMKernel-Report.rtf'
    distractor_name = 'AMKernel-Report-copy.rtf'
    existing_name = 'AMKernel-Existing.rtf'
    list_target = str(Path('List')/'Target'/'AMKernel-Report.rtf')
    list_distractor = str(Path('List')/'Distractor'/'AMKernel-Report.rtf')
    list_items = {str(Path('List')/('AMKernel-Item-%02d.txt' % index)) for index in range(6)}
    checks['distractorUnchanged'] = after_files.get(distractor_name) == initial_files.get(distractor_name)
    checks['collisionDestinationUnchanged'] = after_files.get(existing_name) == initial_files.get(existing_name)
    checks['listTargetDocumentUnchanged'] = after_files.get(list_target) == initial_files.get(list_target)
    checks['listDistractorDocumentUnchanged'] = after_files.get(list_distractor) == initial_files.get(list_distractor)
    checks['listDistractorItemsUnchanged'] = all(after_files.get(name) == initial_files.get(name) for name in list_items)
    marker_scenarios = {'M2','M6','M7'}
    if scenario == 'M4':
        expected_names = initial_names | set(inserted_expected)
        checks['onlyAuthorizedInsertions'] = after_names == expected_names and all(after_files.get(name) == initial_files.get(name) for name in initial_names)
        checks['insertedFilesMatch'] = all(after_files.get(name) == value for name,value in inserted_expected.items())
    elif scenario in marker_scenarios:
        checks['targetMarkerPersisted'] = after_files.get(source_name) != initial_files.get(source_name)
        checks['onlyTargetChanged'] = after_names == initial_names and all(after_files.get(name) == initial_files.get(name) for name in initial_names if name != source_name)
    else:
        checks['allInitialFilesUnchanged'] = after_names == initial_names and all(after_files.get(name) == value for name,value in initial_files.items())
        checks['targetFileUnchanged'] = after_files.get(source_name) == initial_files.get(source_name)
    return checks


def raw_call(method, path, payload=None, timeout=10):
    data = json.dumps(payload).encode() if payload is not None else None
    request = urllib.request.Request(endpoint + path, data=data, method=method, headers={'Content-Type':'application/json'})
    try:
        with urllib.request.urlopen(request,timeout=timeout) as response:
            body = response.read(65536)
            return response.status, json.loads(body) if body else None
    except urllib.error.HTTPError as error:
        return error.code, None
    except Exception:
        return None, None


def _safe_emergency_action(method, path, status, action):
    return {'method':method,'pathKind':_path_kind(path),'status':status,'action':action}


def _owned_sessions(txns):
    sessions = []
    for txn in txns or []:
        if not isinstance(txn,dict):
            continue
        path = txn.get('path') if isinstance(txn.get('path'),str) else ''
        if txn.get('method') == 'POST' and path == '/session' and txn.get('status') == 200 and isinstance(txn.get('sessionCreated'),str):
            text = json.dumps(txn.get('request'),ensure_ascii=False) + json.dumps(returned(txn),ensure_ascii=False)
            bundle = next((candidate for candidate in (TEXTEDIT,FINDER) if candidate in text),None)
            sessions.append({'id':txn['sessionCreated'],'sha256':digest(txn['sessionCreated']),'bundle':bundle,'deleted':False})
        elif txn.get('method') == 'DELETE' and path.startswith('/session/'):
            sid = session_id_of(path)
            for session in sessions:
                if sid == session['id']:
                    session['deleted'] = True
    return sessions


def _raw_window_title(sid, element):
    status, payload = raw_call('GET','/session/' + sid + '/element/' + element + '/attribute/title')
    if status != 200 or not isinstance(payload,dict) or not isinstance(payload.get('value'),str):
        return None
    return payload['value']


def _raw_find_windows(sid):
    status, payload = raw_call('POST','/session/' + sid + '/elements',{'using':'class chain','value':'**/XCUIElementTypeWindow'})
    if status != 200 or not isinstance(payload,dict) or not isinstance(payload.get('value'),list):
        return []
    return [item[ELEMENT_KEY] for item in payload['value'] if isinstance(item,dict) and isinstance(item.get(ELEMENT_KEY),str)]


def _raw_find_close(sid, window):
    status, payload = raw_call('POST','/session/' + sid + '/element/' + window + '/element',{'using':'accessibility id','value':'_XCUI:Close'})
    if status != 200 or not isinstance(payload,dict) or not isinstance(payload.get('value'),dict):
        return None
    value = payload['value'].get(ELEMENT_KEY)
    return value if isinstance(value,str) else None


def emergency_restore(reason, before, txns, ownership):
    evidence = {'attempted':True,'reason':reason,'actions':[],'resolved':False,'texteditGone':False,'finderOwnedClosed':False,'frontmostRestored':False}
    all_sessions = _owned_sessions(txns)
    sessions = [session for session in all_sessions if not session.get('deleted')]
    if not sessions:
        evidence['unresolved'] = 'no-owned-live-session'
        return evidence
    finder_sessions = [session for session in sessions if session.get('bundle') == FINDER]
    finder_created = any(session.get('bundle') == FINDER for session in all_sessions)
    if not finder_created:
        evidence['finderOwnedClosed'] = True
    elif finder_sessions and ownership.get('valid') is True:
        facts = _finder_ownership(build_protocol(txns,expected),ownership,expected)
        supported = all(facts.get(key) is True for key in ('baselineObserved','newWindowObserved','ownedWindowBound','navigationBound'))
        matching_sessions = [session for session in finder_sessions if digest(session['id']) == ownership.get('sessionSha256')]
        if supported and len(matching_sessions) == 1:
            sid = matching_sessions[0]['id']
            windows = _raw_find_windows(sid)
            titles = [(window,_raw_window_title(sid,window)) for window in windows]
            matches = [window for window,title in titles if title is not None and digest(title) == ownership.get('ownedWindowSha256')]
            baseline = set(ownership.get('baselineWindowSha256s',[]))
            observed = {digest(title) for _window,title in titles if title is not None}
            if len(matches) == 1 and baseline <= observed and ownership.get('ownedWindowSha256') not in baseline:
                close = _raw_find_close(sid,matches[0])
                if close:
                    status, _payload = raw_call('POST','/session/' + sid + '/element/' + close + '/click')
                    evidence['actions'].append(_safe_emergency_action('POST','/session/' + sid + '/element/' + close + '/click',status,'close-owned-finder-window'))
                    remaining = [_raw_window_title(sid,window) for window in _raw_find_windows(sid)]
                    remaining_hashes = {digest(title) for title in remaining if title is not None}
                    evidence['finderOwnedClosed'] = status == 200 and baseline <= remaining_hashes and ownership.get('ownedWindowSha256') not in remaining_hashes
    if before.get('frontmostBundleId'):
        for session in sessions:
            status, _payload = raw_call('POST','/session/' + session['id'] + '/execute/sync',{'script':'macos: activateApp','args':[{'bundleId':before['frontmostBundleId']}]})
            evidence['actions'].append(_safe_emergency_action('POST','/session/' + session['id'] + '/execute/sync',status,'restore-frontmost'))
            if status == 200:
                evidence['frontmostRestored'] = True
                break
    try:
        after = desktop()
    except Exception:
        after = None
    evidence['afterDesktop'] = after
    evidence['texteditGone'] = bool(after is not None and after.get('textedit') == before.get('textedit'))
    evidence['resolved'] = bool(evidence['texteditGone'] and evidence['frontmostRestored'] and evidence['finderOwnedClosed'])
    return evidence


def read_ownership(path):
    result = {'valid':False,'receiptSha256':None,'sessionSha256':None,'baselineWindowCount':None,'baselineWindowSha256s':[],'ownedWindowSha256':None}
    if not path.exists():
        return result
    try:
        raw = path.read_bytes()
        result['receiptSha256'] = hashlib.sha256(raw).hexdigest()
        value = json.loads(raw)
    except Exception:
        return result
    if not isinstance(value,dict) or set(value) != {'schemaVersion','sessionSha256','baselineWindowCount','baselineWindowSha256s','ownedWindowSha256','createdAt'}:
        return result
    if value.get('schemaVersion') != 1:
        return result
    if not isinstance(value.get('sessionSha256'),str) or not re.fullmatch(r'[0-9a-f]{64}',value['sessionSha256']):
        return result
    if not isinstance(value.get('ownedWindowSha256'),str) or not re.fullmatch(r'[0-9a-f]{64}',value['ownedWindowSha256']):
        return result
    if not isinstance(value.get('createdAt'),str) or not value['createdAt']:
        return result
    baseline = value.get('baselineWindowSha256s')
    if not isinstance(baseline,list) or not all(isinstance(item,str) and re.fullmatch(r'[0-9a-f]{64}',item) for item in baseline):
        return result
    if len(set(baseline)) != len(baseline):
        return result
    if not isinstance(value.get('baselineWindowCount'),int) or isinstance(value.get('baselineWindowCount'),bool) or value['baselineWindowCount'] < 0:
        return result
    result.update({'valid':True,'sessionSha256':value['sessionSha256'],'baselineWindowCount':value['baselineWindowCount'],'baselineWindowSha256s':sorted(baseline),'ownedWindowSha256':value['ownedWindowSha256']})
    return result


